function renderProfileRecords(rows){return rows.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>指标 / Metric</th><th>期间 / Period</th><th>频率 / Frequency</th><th>数值 / Value</th><th>币种 / Currency</th><th>类型 / Type</th><th>报告日期 / Report Date</th><th>来源 / Source</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(BY_EN[r.metric]?.zh||r.metric)}<br><span class="muted">${esc(r.metric)}</span></td><td>${esc(r.period)}</td><td>${esc(r.frequency||'N/A')}</td><td class="mono">${fmt(r.value)} ${esc(r.unit)}</td><td>${esc(r.currency||'N/A')}</td><td><span class="tag">${esc(r.dataType||'N/A')}</span>${r.notes?`<br><span class="muted">${esc(r.notes)}</span>`:''}</td><td>${esc(r.reportDate||'N/A')}</td><td><a href="${esc(r.sourceUrl)}" target="_blank">来源 ↗</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div><b>暂无数据 / No data</b>批量录入后会自动显示在这里。</div></div>`}
function renderBatchEntry(){app.innerHTML=`<div class="section-head"><div><p class="eyebrow">P1 / BILINGUAL BATCH ENTRY</p><h2>智能批量财务录入 / Smart Batch Financial Entry</h2><p>所有指标一次展开；粘贴财报文字后自动识别，无法确认的字段保持为空。</p></div><span class="tag">${FIELDS.length} METRICS</span></div><section class="smart-import"><div><h3>粘贴财报文字 / Paste Financial Text</h3><p>支持中英文、冒号、表格复制文本和常见单位。识别使用字段别名匹配与字符串相似度，不会编造缺失数据。</p></div><textarea id="smartText" placeholder="例如 / Example:\nRevenue: 60.9 billion USD\n毛利率 72.7%\n经营现金流：280.9 亿美元"></textarea><div class="smart-actions"><button class="primary" id="recognizeBtn">识别并填入 / Recognize & Fill</button><button class="ghost" id="clearMetricsBtn">清空指标 / Clear</button><span id="recognizeStatus" class="muted">等待输入 / Waiting</span></div></section><form id="batchForm"><section class="entry-meta panel"><div class="form-grid"><div class="field"><label>公司名称 / Company Name *</label><input name="companyName" list="companyNames" required placeholder="直接输入，不需要预选 / Type a name"><datalist id="companyNames">${state.companies.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist></div><div class="field"><label>股票代码 / Ticker</label><input name="ticker" placeholder="NVDA / 688981"></div><div class="field"><label>国家 / Country *</label><select name="country" required><option value="美国">美国 / United States</option><option value="中国">中国 / China</option></select></div><div class="field"><label>行业板块 / Industry *</label><select name="industryId" required>${industryOptions('semiconductor')}</select></div><div class="field"><label>期间 / Period *</label><input name="period" required placeholder="FY2025 / 2025 Q1"></div><div class="field"><label>频率 / Frequency *</label><select name="frequency"><option>年度 / Annual</option><option>季度 / Quarterly</option></select></div><div class="field"><label>报告日期 / Report Date *</label><input name="reportDate" required placeholder="2025-01-26（可随时修改）"></div><div class="field"><label>默认单位 / Default Unit</label><input name="defaultUnit" value="million"></div><div class="field"><label>币种 / Currency *</label><select name="currency"><option>USD</option><option>CNY</option></select></div><div class="field"><label>数据类型 / Data Type</label><select name="dataType"><option>原始数据 / Reported</option><option>计算数据 / Calculated</option><option>估算数据 / Estimated</option></select></div><div class="field wide"><label>来源链接 / Source URL *</label><input type="url" name="sourceUrl" required placeholder="https://…"></div></div></section><section class="batch-groups">${GROUPS.map(g=>`<article class="batch-group"><header><div><h3>${g.zh}</h3><span>${g.en}</span></div><em>${g.items.length} ITEMS</em></header><div class="batch-header"><span>指标 / Metric</span><span>数值 / Value</span><span>单位 / Unit</span></div>${g.items.map(([en,zh])=>`<div class="metric-row" data-metric="${esc(en)}"><label><b>${esc(zh)}</b><small>${esc(en)}</small></label><input class="metric-value" name="metric:${esc(en)}" type="number" step="any" placeholder="留空 / N/A"><input class="metric-unit" name="unit:${esc(en)}" placeholder="默认单位"></div>`).join('')}</article>`).join('')}</section><div class="batch-submit"><div><b id="filledCount">0 / ${FIELDS.length}</b><span> 已填写 / filled</span></div><button class="primary" type="submit">一次保存全部数据 / Save All</button></div></form>`;$('#recognizeBtn').onclick=recognizeText;$('#clearMetricsBtn').onclick=()=>{$$('.metric-value,.metric-unit').forEach(x=>x.value='');updateFilled()};$$('.metric-value').forEach(x=>x.oninput=updateFilled);$('#batchForm').onsubmit=saveBatch}
function norm(s){return String(s||'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9\u4e00-\u9fff]+/g,' ').trim()}
function dice(a,b){a=norm(a).replace(/\s/g,''),b=norm(b).replace(/\s/g,'');if(!a||!b)return 0;if(a===b)return 1;const m=new Map;for(let i=0;i<a.length-1;i++){const x=a.slice(i,i+2);m.set(x,(m.get(x)||0)+1)}let hit=0;for(let i=0;i<b.length-1;i++){const x=b.slice(i,i+2),n=m.get(x)||0;if(n){hit++;m.set(x,n-1)}}return 2*hit/Math.max(1,a.length+b.length-2)}
function metricMatch(line){const nl=norm(line);let best=null,score=0;for(const f of FIELDS){for(const a of [f.en,f.zh,...(aliases[f.en]||[])]){const na=norm(a),direct=nl.includes(na)?na.length+10:0;if(direct>score){best=f;score=direct}else if(!direct){const label=norm(line.split(/[:：=\t]|(?=[-+]?\d)/)[0]),s=dice(label,na);if(s>.62&&s*10>score){best=f;score=s*10}}}}return best}
function parseNumber(line){const matches=[...String(line).matchAll(/[-+]?\(?\d[\d,]*(?:\.\d+)?\)?\s*(%|万亿|亿|万|兆|trillion|billion|million|thousand|tn|bn|mn|k)?/gi)];if(!matches.length)return null;let m=matches[matches.length-1],raw=m[0].replace(/[(),\s]/g,''),unit=(m[1]||'').toLowerCase(),negative=/^\(/.test(m[0]),n=parseFloat(raw);if(!Number.isFinite(n))return null;if(negative)n=-n;return{value:n,unit:unit||''}}
function recognizeText(){const text=$('#smartText').value.trim();if(!text){toast('请先粘贴文字 / Paste text first');return}const found=new Map,unmatched=[];text.split(/\r?\n|;|；/).map(x=>x.trim()).filter(Boolean).forEach(line=>{const field=metricMatch(line),num=parseNumber(line);if(field&&num&&!found.has(field.en))found.set(field.en,num);else if(/\d/.test(line))unmatched.push(line)});for(const [metric,item]of found){const row=$(`.metric-row[data-metric="${CSS.escape(metric)}"]`);if(row){$('.metric-value',row).value=item.value;$('.metric-unit',row).value=item.unit}}updateFilled();$('#recognizeStatus').innerHTML=`<b class="positive">已识别 ${found.size} 项 / ${found.size} recognized</b>${unmatched.length?` · ${unmatched.length} 行未确认，已留空`:''}`;toast(`识别完成：${found.size} 个指标`)}
function updateFilled(){const n=$$('.metric-value').filter(x=>x.value!=='').length;$('#filledCount').textContent=`${n} / ${FIELDS.length}`}
function saveBatch(e){e.preventDefault();const form=e.target,fd=new FormData(form),name=fd.get('companyName').trim();let c=state.companies.find(x=>norm(x.name)===norm(name));if(!c){c={id:uid(),name,ticker:fd.get('ticker').trim(),country:fd.get('country'),industryId:fd.get('industryId'),listed:fd.get('ticker').trim()?'上市 / Public':'未指定 / Unspecified',founded:'',description:'',products:'',customers:'',revenueSources:'',businessModel:'',createdAt:now(),updatedAt:now()};state.companies.push(c)}else{c.ticker=fd.get('ticker').trim()||c.ticker;c.country=fd.get('country');c.industryId=fd.get('industryId');c.updatedAt=now()}const entries=FIELDS.map(f=>{const v=fd.get(`metric:${f.en}`);if(v==='')return null;return{metric:f.en,value:Number(v),unit:fd.get(`unit:${f.en}`)||fd.get('defaultUnit'),currency:fd.get('currency')}}).filter(Boolean);if(!entries.length){toast('至少填写一个指标 / Enter at least one metric');return}const duplicates=entries.filter(x=>state.financials.some(r=>r.companyId===c.id&&r.metric===x.metric&&r.period===fd.get('period')));if(duplicates.length&&!confirm(`发现 ${duplicates.length} 条相同公司、指标和期间的记录。继续将更新这些记录。`))return;for(const x of entries){const old=state.financials.find(r=>r.companyId===c.id&&r.metric===x.metric&&r.period===fd.get('period')),record={...old,...x,id:old?.id||uid(),companyId:c.id,frequency:fd.get('frequency').startsWith('年度')?'年度':'季度',period:fd.get('period'),reportDate:fd.get('reportDate'),sourceUrl:fd.get('sourceUrl'),dataType:fd.get('dataType'),createdAt:old?.createdAt||now(),updatedAt:now()};if(old)state.financials[state.financials.indexOf(old)]=record;else state.financials.push(record);state.audits.push({id:uid(),recordId:record.id,action:old?'update':'create',before:old||null,after:record,createdAt:now()})}save();toast(`已保存 ${entries.length} 条数据 / Saved`);renderBatchEntry()}
function renderAnalytics(){
 const heading=`<div class="section-head"><div><h2>财务分析 / Financial Analytics</h2><p>图表只读取已录入数据。</p></div></div>`;
 if(!state.companies.length){app.innerHTML=heading+`<div class="empty"><div><b>暂无公司 / No companies</b>请先批量录入。</div></div>`;return}
 const companies=state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
 const metricOpts=FIELDS.map(f=>`<option value="${f.en}">${f.zh} / ${f.en}</option>`).join('');
 app.innerHTML=heading+`<div class="filters"><div class="field"><label>公司 / Company</label><select id="anCompany">${companies}</select></div><div class="field"><label>指标 / Metric</label><select id="anMetric">${metricOpts}</select></div><div class="field"><label>频率 / Frequency</label><select id="anFrequency"><option value="年度">年度 / Annual</option><option value="季度">季度 / Quarterly</option></select></div><div class="field"><label>显示 / Mode</label><select id="anMode"><option value="absolute">绝对值 / Absolute</option><option value="growth">同比 / Growth</option><option value="index">基期=100 / Indexed</option></select></div></div><div class="chart-card" id="analyticsChart"></div>`;
 ['anCompany','anMetric','anFrequency','anMode'].forEach(id=>$('#'+id).onchange=()=>drawChart($('#analyticsChart'),[$('#anCompany').value],$('#anMetric').value,$('#anFrequency').value,$('#anMode').value));drawChart($('#analyticsChart'),[state.companies[0].id],FIELDS[0].en,'年度','absolute');
}
let compare={industryId:'semiconductor',companies:[],metric:'Revenue',frequency:'年度',mode:'index'};
function renderComparison(){
 const eligible=state.companies.filter(c=>c.industryId===compare.industryId);
 const industryButtons=state.industries.map(i=>`<button class="industry-pill ${i.id===compare.industryId?'active':''}" data-industry="${i.id}">${esc(i.name)}<br><span>${esc(i.en)}</span></button>`).join('');
 const companyChecks=eligible.length?eligible.map(c=>`<label class="company-check active"><input type="checkbox" value="${c.id}" checked>${esc(c.name)}</label>`).join(''):`<span class="muted">暂无公司 / No companies</span>`;
 const metricOpts=FIELDS.map(f=>`<option value="${f.en}" ${f.en===compare.metric?'selected':''}>${f.zh} / ${f.en}</option>`).join('');
 app.innerHTML=`<div class="section-head"><div><h2>同行业比较 / Peer Comparison</h2><p>公司在批量录入时按行业自动归类。</p></div></div><div class="industry-picker">${industryButtons}</div><div class="compare-layout" style="margin-top:12px"><aside class="control-panel"><div class="control-group"><h3>公司 / COMPANIES</h3><div id="compareCompanies">${companyChecks}</div></div><div class="control-group"><h3>指标 / METRIC</h3><select id="compareMetric" class="search-input">${metricOpts}</select></div><div class="control-group"><h3>频率 / FREQUENCY</h3><div class="segmented"><button data-frequency="年度" class="${compare.frequency==='年度'?'active':''}">年度</button><button data-frequency="季度" class="${compare.frequency==='季度'?'active':''}">季度</button></div></div><div class="control-group"><h3>方式 / MODE</h3><div class="segmented"><button data-mode="absolute" class="${compare.mode==='absolute'?'active':''}">绝对值</button><button data-mode="growth" class="${compare.mode==='growth'?'active':''}">同比</button><button data-mode="index" class="${compare.mode==='index'?'active':''}">基期=100</button></div></div></aside><div class="chart-card" id="compareChart"></div></div>`;
 compare.companies=eligible.map(c=>c.id);drawChart($('#compareChart'),compare.companies,compare.metric,compare.frequency,compare.mode);
 $('#compareMetric').onchange=e=>{compare.metric=e.target.value;drawChart($('#compareChart'),compare.companies,compare.metric,compare.frequency,compare.mode)};
 $$('#compareCompanies input').forEach(x=>x.onchange=()=>{compare.companies=$$('#compareCompanies input:checked').map(i=>i.value);drawChart($('#compareChart'),compare.companies,compare.metric,compare.frequency,compare.mode)});
}
function chartSeries(ids,metric,frequency,mode){return ids.map(cid=>{let vals=state.financials.filter(r=>r.companyId===cid&&r.metric===metric&&r.frequency===frequency).sort((a,b)=>a.period.localeCompare(b.period)).map(r=>({period:r.period,value:Number(r.value),currency:r.currency,unit:r.unit||''}));if(mode==='growth')vals=vals.map((x,i)=>({...x,value:i&&vals[i-1].value!==0?(x.value/vals[i-1].value-1)*100:null,unit:'%'})).filter(x=>x.value!==null);if(mode==='index'){const base=vals.find(x=>x.value!==0);vals=base?vals.map(x=>({...x,value:x.value/base.value*100,unit:'指数',currency:''})):[]}return{company:company(cid),values:vals}})}
function drawChart(root,ids,metric,frequency,mode){
 const series=chartSeries(ids,metric,frequency,mode),all=series.flatMap(s=>s.values),periods=[...new Set(all.map(x=>x.period))].sort(),colors=['#5b5ce2','#7758d8','#3979d7','#9b59d0','#4f46c8'];
 if(!all.length){root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DATABASE CHART</p><h3>${esc(BY_EN[metric]?.zh)} / ${esc(metric)}</h3></div></div><div class="empty"><div><b>暂无可绘制数据 / No chart data</b>缺失值保持 N/A，不填充为 0。</div></div>`;return}
 const W=900,H=300,p={l:105,r:45,t:38,b:42},vs=all.map(x=>x.value),rawLo=Math.min(...vs),rawHi=Math.max(...vs),span=rawHi===rawLo?Math.max(Math.abs(rawHi)*.2,1):rawHi-rawLo,low=rawLo-span*.14,hi=rawHi+span*.14,range=hi-low;
 const x=k=>p.l+periods.indexOf(k)/Math.max(1,periods.length-1)*(W-p.l-p.r),y=v=>p.t+(hi-v)/range*(H-p.t-p.b),ticks=[0,.25,.5,.75,1].map(q=>hi-q*range);
 const num=v=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:Math.abs(range)<10?2:Math.abs(range)<100?1:0});
 const unit=v=>mode==='growth'?'%':mode==='index'?'指数':String(v.unit||'').includes('%')?'%':[v.currency,v.unit].filter(Boolean).join(' ')||'数值';
 const axisUnit=unit(all[0]);
 root.innerHTML=`<div class="chart-head"><div><p class="eyebrow">DATABASE CHART</p><h3>${esc(BY_EN[metric]?.zh)} / ${esc(metric)}</h3><p>${mode==='index'?'基期=100 / Indexed':mode==='growth'?'同比增长 / Growth':'绝对值 / Absolute'} · 单位 / Unit: ${esc(axisUnit)}</p></div></div><div class="chart-wrap"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${ticks.map((v,i)=>{const yy=p.t+i*(H-p.t-p.b)/4;return`<line x1="${p.l}" y1="${yy}" x2="${W-p.r}" y2="${yy}" class="grid-line"/><text x="${p.l-10}" y="${yy+4}" text-anchor="end" class="axis-number">${esc(num(v))} ${esc(axisUnit)}</text>`}).join('')}${periods.map(k=>`<text x="${x(k)}" y="${H-9}" text-anchor="middle" class="axis-label">${esc(k)}</text>`).join('')}${series.map((s,i)=>`<polyline points="${s.values.map(v=>`${x(v.period)},${y(v.value)}`).join(' ')}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="3"/>${s.values.map(v=>`<circle cx="${x(v.period)}" cy="${y(v.value)}" r="4" fill="${colors[i%colors.length]}"></circle><text x="${x(v.period)}" y="${Math.max(14,y(v.value)-10-i*11)}" text-anchor="middle" class="point-label" fill="${colors[i%colors.length]}">${esc(num(v.value))} ${esc(unit(v))}</text>`).join('')}`).join('')}</svg></div><div class="legend">${series.map((s,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(s.company?.name)}</span>`).join('')}</div>`
}
function renderJournal(){app.innerHTML=`<div class="section-head"><div><h2>研究日志 / Research Journal</h2><p>记录每日发现、数据、思考、问题和来源。</p></div><button class="primary" data-action="add-journal">＋ 新增 / Add</button></div><div id="journalList">${state.journals.length?[...state.journals].sort((a,b)=>b.date.localeCompare(a.date)).map(j=>`<article class="journal-card"><header><div><span class="tag">${esc(j.type)}</span><h3>${esc(j.title||j.discovery)}</h3></div><span class="mono muted">${esc(j.date)}</span></header><p>${esc(j.discovery)}</p><footer><span>${esc(company(j.companyId)?.name||'通用研究')}</span><button class="link-button" data-action="edit-journal" data-id="${j.id}">编辑 / Edit</button></footer></article>`).join(''):`<div class="empty"><div><b>暂无日志 / No journal entries</b></div></div>`}</div>`}
